(async()=>{const out=[],wait=ms=>new Promise(r=>setTimeout(r,ms)),el=document.createElement('div');
for(const mode of['pause-play','cancel-play','finish-play']){const a=el.animate(),events=[];a.finished.catch(()=>{});a.onfinish=()=>events.push('finish');a.oncancel=()=>events.push('cancel');setTimeout(()=>{a[mode.split('-')[0]]();events.push('first')},4);setTimeout(()=>{a.play();a.finished.catch(()=>{});events.push('play')},6);setTimeout(()=>events.push('middle:'+a.playState),12);await wait(35);out.push([mode,events.slice()]);a.finished.catch(()=>{});a.cancel();}
{const log=[],p=new Proxy({bubbles:true,cancelable:true,composed:true,currentTime:{valueOf(){log.push('current-number');return 1}},timelineTime:{valueOf(){log.push('timeline-number');return 2}}},{get(t,k){log.push('get:'+String(k));return Reflect.get(t,k)},has(t,k){log.push('has:'+String(k));return Reflect.has(t,k)},getOwnPropertyDescriptor(t,k){log.push('own:'+String(k));return Reflect.getOwnPropertyDescriptor(t,k)}});const e=new AnimationPlaybackEvent({toString(){log.push('type');return'x'}},p);out.push(['event-init-proxy',{log,bubbles:e.bubbles,cancelable:e.cancelable,composed:e.composed}]);}
{const log=[],base={get bubbles(){log.push('bubbles');return true},get cancelable(){log.push('cancelable');return true},get composed(){log.push('composed');return true}},init=Object.create(base);const e=new AnimationPlaybackEvent('x',init);out.push(['event-inherited',{log,bubbles:e.bubbles,cancelable:e.cancelable,composed:e.composed}]);}
{const a=el.animate(),effect=()=>{},timeline=new Proxy({},{get(){throw Error('getter')}});a.effect=effect;a.timeline=timeline;a.pause();out.push(['object-identity',{effect:a.effect===effect,timeline:a.timeline===timeline}]);a.finished.catch(()=>{});a.cancel();}
const frame=document.createElement('iframe');frame.src='/';const loaded=new Promise(r=>frame.onload=r);document.body.append(frame);await loaded;const child=frame.contentWindow;
for(const [name,create,finish]of[['main-child-finish',()=>el.animate(),child.Animation.prototype.finish],['child-main-finish',()=>child.document.createElement('div').animate(),Animation.prototype.finish]]){const a=create();const event=await new Promise(resolve=>{a.onfinish=resolve;finish.call(a)});out.push([name,{main:event instanceof AnimationPlaybackEvent,child:event instanceof child.AnimationPlaybackEvent,target:event.target===a}]);}
for(const[name,make,cancel]of[['main-child-cancel',()=>el.animate(),child.Animation.prototype.cancel],['child-main-cancel',()=>child.document.createElement('div').animate(),Animation.prototype.cancel]]){const a=make(),first=a.finished;first.catch(()=>{});const event=await new Promise(resolve=>{a.oncancel=resolve;cancel.call(a)});a.finished.catch(()=>{});let error;await first.catch(e=>error={main:e instanceof DOMException,child:e instanceof child.DOMException});out.push([name,{main:event instanceof AnimationPlaybackEvent,child:event instanceof child.AnimationPlaybackEvent,error}]);}
frame.remove();return out;})()
